//! Differential test: the ported text functions must give exactly the
//! outputs Yomitan's own functions gave for 16k inputs
//! (tests/fixtures/yomitan/japanese-functions-golden.json, generated by
//! scripts/port/dump-ja-golden.mjs).

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use jisho_ja::{
    collapse_emphatic_sequences, convert_alphabetic_to_kana, convert_alphanumeric_to_full_width,
    convert_full_width_alphanumeric_to_normal, convert_half_width_kana_to_full_width,
    convert_hiragana_to_katakana, convert_katakana_to_hiragana, convert_variants,
    is_string_entirely_kana, is_string_partially_japanese, normalize_cjk_compatibility_characters,
    normalize_combining_characters, normalize_radicals,
};
use serde_json::Value;

const MAX_REPORTED: usize = 10;

/// A ported function under test, named as in the oracle file.
type StringFunction = (&'static str, fn(&str) -> String);
type BoolFunction = (&'static str, fn(&str) -> bool);

#[test]
fn text_functions_match_yomitan_outputs() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/yomitan/japanese-functions-golden.json"
    );
    let data: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let inputs: Vec<&str> = data["inputs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap())
        .collect();
    assert!(inputs.len() > 10_000, "oracle too small: {}", inputs.len());

    let string_functions: [StringFunction; 13] = [
        ("convertKatakanaToHiragana", |s| {
            convert_katakana_to_hiragana(s, false)
        }),
        ("convertKatakanaToHiraganaKeepProlonged", |s| {
            convert_katakana_to_hiragana(s, true)
        }),
        ("convertHiraganaToKatakana", convert_hiragana_to_katakana),
        (
            "convertAlphanumericToFullWidth",
            convert_alphanumeric_to_full_width,
        ),
        (
            "convertFullWidthAlphanumericToNormal",
            convert_full_width_alphanumeric_to_normal,
        ),
        (
            "convertHalfWidthKanaToFullWidth",
            convert_half_width_kana_to_full_width,
        ),
        (
            "normalizeCombiningCharacters",
            normalize_combining_characters,
        ),
        (
            "normalizeCJKCompatibilityCharacters",
            normalize_cjk_compatibility_characters,
        ),
        ("normalizeRadicals", normalize_radicals),
        ("collapseEmphaticSequences", |s| {
            collapse_emphatic_sequences(s, false)
        }),
        ("collapseEmphaticSequencesFull", |s| {
            collapse_emphatic_sequences(s, true)
        }),
        ("convertAlphabeticToKana", convert_alphabetic_to_kana),
        ("convertVariants", convert_variants),
    ];
    let bool_functions: [BoolFunction; 2] = [
        ("isStringPartiallyJapanese", is_string_partially_japanese),
        ("isStringEntirelyKana", is_string_entirely_kana),
    ];

    let mut report = Vec::new();
    for (name, function) in string_functions {
        let expected = data["outputs"][name].as_array().unwrap();
        let mut bad = 0;
        for (input, want) in inputs.iter().zip(expected) {
            let got = function(input);
            if got != want.as_str().unwrap() {
                bad += 1;
                if bad <= MAX_REPORTED {
                    report.push(format!("{name}({input:?}) = {got:?}, Yomitan {want}"));
                }
            }
        }
        if bad > 0 {
            report.push(format!("{name}: {bad} mismatches"));
        }
    }
    for (name, function) in bool_functions {
        let expected = data["outputs"][name].as_array().unwrap();
        for (input, want) in inputs.iter().zip(expected) {
            if function(input) != want.as_bool().unwrap() {
                report.push(format!("{name}({input:?}) != {want}"));
            }
        }
    }
    assert!(report.is_empty(), "{}", report.join("\n"));
}
